from typing import Set, Tuple
Point = Tuple[int, int]
Block = Tuple[Point, Point, Point]
points = tuple(product(range(3), repeat=2))
def third(x: Point, y: Point) -> Point:
    return (-(x[0] + y[0]) % 3, -(x[1] + y[1]) % 3)
def block(x: Point, y: Point) -> Block:
    a, b, c = sorted((x, y, third(x, y)))
    return a, b, c
blocks: Set[Block] = {block(x, y) for x, y in combinations(points, 2)}
assert len(blocks) == 12
for item in sorted(blocks):
    print(item)

from itertools import product
from typing import Tuple
Point = Tuple[int, int]
points = tuple(product(range(3), repeat=2))
def add(x: Point, y: Point) -> Point:
    return ((x[0] + y[0]) % 3, (x[1] + y[1]) % 3)
def third(x: Point, y: Point) -> Point:
    return (-(x[0] + y[0]) % 3, -(x[1] + y[1]) % 3)
checked = 0
for x, y, t in product(points, repeat=3):
    assert third(add(x, t), add(y, t)) == add(third(x, y), t)
    checked += 1
print(f"Translation covariance holds in all {checked} cases.")

