from typing import Callable, Iterable, Tuple, TypeVar
T = TypeVar("T")
def preserves_completion(elements: Iterable[T], add: Callable[[T,T],T],
                         neg: Callable[[T],T], f: Callable[[T],T]) -> bool:
    values = list(elements)
    third = lambda x,y: neg(add(x,y))
    return all(f(third(x,y)) == third(f(x),f(y))
               for x in values for y in values)

